stylesheet:
html,
body { background: #171b1d; }

body,
#container {
	color: #ccc;
	font-family: Arial, Helvetica, sans-serif;
	font-size: 13px;
}

#container { min-width: 0; }

a:link,
a:visited { color: #7289da; }

a:hover,
a:active {
	color: #b56ac4;
	text-decoration: none;
}

.wrapper {
	box-sizing: border-box;
	width: calc(100% - 32px);
	min-width: 0;
	max-width: 1180px;
}

#logo {
	min-height: 115px;
	padding: 20px 0;
	background-color: #151515;
	background-image: linear-gradient(rgba(8, 8, 12, 0.42), rgba(8, 8, 12, 0.62)), url(images/space-cadet/banner-bg.jpg);
	background-position: center;
	background-size: cover;
	border-bottom: 1px solid #262626;
	display: flex;
	align-items: center;
}

#logo .wrapper {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 32px;
}

#logo img {
	display: block;
	max-width: 420px;
	width: auto;
	height: auto;
}

#logo ul.top_links {
	margin: 0;
	display: flex;
	flex-wrap: wrap;
	justify-content: flex-end;
	gap: 6px;
	max-width: 640px;
}

#logo ul.menu li {
	margin: 0;
	display: block;
}

#header ul.menu li a {
	padding: 8px 10px;
	background-image: none;
	border-radius: 3px;
	color: #fff;
}

#header ul.menu li a i {
	color: #7289da;
	font-size: 13px;
}

#header ul.menu li a:hover { background-color: #262626; }

#panel .upper {
	background: #0e0e0e;
	border-color: #262626 #101010;
}

#panel .lower {
	background: #181818;
	color: #969696;
	border-color: #262626;
}

#panel .upper .wrapper,
#panel .lower .wrapper {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 20px;
}

#panel ul.menu {
	margin: 0;
	display: flex;
	align-items: center;
	flex-wrap: wrap;
	gap: 8px 18px;
}

#panel ul.menu li {
	margin: 0;
	display: inline-block;
}

#panel a i {
	color: #7289da;
	font-size: 12px;
}

#panel .upper,
#panel .lower {
	padding: 3px 0;
}

#panel .lower a {
	display: inline-block;
	padding: 4px 2px;
}

#panel .lower a:hover { color: #fff; }

#panel .lower ul.panel_links,
#panel .lower ul.user_links { float: none; }

#panel .lower br.clear { display: none; }

#panel .lower a:link,
#panel .lower a:visited,
#panel .lower a:hover,
#panel .lower a:active { color: #ccc; }

#search {
	order: 2;
	float: none;
	display: flex;
	gap: 5px;
}

#search input { margin: 0; }

#search input.textbox {
	background: #181818;
	border-color: #4a4a4a;
	box-shadow: inset 0 1px 2px #0a0a0a;
}

#search input.textbox:hover { border-color: #606060; }

#search input.textbox:focus {
	background: #1d1d1d;
	border-color: #7289da;
	box-shadow: 0 0 0 1px rgba(114, 137, 218, 0.25);
}

#content {
	box-sizing: border-box;
	padding: 18px 0 28px;
	background: transparent;
	color: #d3d3d3;
}

#content .navigation { color: #aaa; }

#content .navigation a:link,
#content .navigation a:visited { color: #7289da; }

.tborder {
	background: #161616;
	border: 1px solid #0d0d0d;
	border-radius: 3px;
	box-shadow: inset 0 0 1px 1px #262626, 0 8px 24px rgba(0, 0, 0, 0.22);
	overflow: hidden;
}

.thead {
	background: #151515;
	color: #fff;
	border-left: 3px solid #7289da;
	border-bottom-color: #080808;
	box-shadow: inset 0 0 1px 1px #292929;
	text-transform: uppercase;
	text-shadow: 1px 1px 0 #070707;
}

.thead a:link,
.thead a:visited,
.thead a:hover,
.thead a:active,
.tcat a:link,
.tcat a:visited,
.tcat a:hover,
.tcat a:active { color: #fff; }

.tcat {
	background: #202020;
	color: #ccc;
	border-top-color: #111;
	border-bottom-color: #303030;
}

.trow1 { background: #181818; }
.trow2 { background: #1c1c1c; }

.trow1,
.trow2 {
	color: #ccc;
	border-color: #101010 #292929 #292929 #101010;
}

.trow_shaded,
.trow_selected,
tr.trow_selected td {
	background: #23232a;
	color: #fff;
}

.tfoot {
	background: #181818;
	color: #ccc;
	border-top: 1px solid #101010;
	border-bottom: 1px solid #262626;
}

.tfoot a:link,
.tfoot a:visited { color: #ccc; }

.tfoot a:hover,
.tfoot a:active { color: #fff; }

table,
.smalltext,
.navigation { color: #ccc; }

.navigation .active { color: #aaa; }

input.textbox,
textarea,
select {
	background: #0e0e0e;
	color: #ccc;
	border: 1px solid #3e3e3e;
}

input.textbox:focus,
textarea:focus,
select:focus {
	border-color: #667bc4;
	box-shadow: 0 0 0 1px #262832;
	outline: 0;
}

input.button,
button,
.button {
	background: #262832;
	color: #fff;
	border: 1px solid #3a3d4c;
	border-radius: 3px;
}

input.button:hover,
button:hover,
.button:hover {
	background: #667bc4;
	border-color: #7289da;
}

.pagination a:hover,
.pagination .pagination_current {
	background: #667bc4;
	border-color: #7289da;
	color: #fff;
}

blockquote,
.codeblock {
	background: #141414;
	border-color: #262832;
}

#footer .upper {
	background: #151515;
	border-color: #262626;
}

#footer .lower {
	background: #0e0e0e;
	color: #969696;
}

#footer a:link,
#footer a:visited,
#footer a:hover,
#footer a:active { color: #ccc; }

@media (max-width: 760px) {
	.wrapper { width: calc(100% - 20px); }
	#logo { min-height: 0; }

	#logo .wrapper,
	#panel .upper .wrapper,
	#panel .lower .wrapper {
		align-items: flex-start;
		flex-direction: column;
	}

	#logo img { max-width: 100%; }
	#logo ul.top_links { justify-content: flex-start; }

	#search {
		order: 0;
		width: 100%;
	}

	#search input.textbox {
		box-sizing: border-box;
		min-width: 0;
		flex: 1;
	}
}
